import logging
import sys
from os import listdir
from os.path import join, dirname, abspath
from functools import wraps
from shutil import copy

python_logger = logging.getLogger("AdminApiLogger")


class AdminApiObject(dict):

    def __init__(self, data):
        for name, value in data.items():
            self[name] = self._wrap(value)

    def _wrap(self, value):
        return AdminApiObject(value) if isinstance(value, dict) else value

    def __getattr__(self, attr):
        return self[attr]

    def __setattr__(self, attr, value):
        self[attr] = value


def wrap_result(function):
    """Convert dict to AdminApiObject"""

    @wraps(function)
    def _wrap(inst, *args, **kw):
        result = function(inst, *args, **kw)
        if isinstance(result, list):
            return [AdminApiObject(item) for item in result]
        return AdminApiObject(result)
    return _wrap


def _search_recursively(d, searched_val):
    """
    search recursively for a key in a nested dict
    """
    result = None
    for k, v in d.items():
        if k == searched_val:
            return v
        if isinstance(v, list):
            result_list = [_search_recursively(i, searched_val) for i in v]
            result = result_list[0] if len(result_list) > 0 else None
        elif isinstance(v, dict):
            result = _search_recursively(v, searched_val)
    return result


def convert_str_with_integers_to_list_of_int(string, separator=","):
    """
    convert string like [1,2,3] to list
    """
    if isinstance(string, list):
        return string
    string = remove_brackets_from_end_of_string(string)
    splitted = string.split(separator)
    return_list = []
    for number in splitted:
        try:
            return_list.append(int(number))
        except (ValueError, TypeError):
            raise ValueError('Conversion error: Value (%s) is not a number e.g. 1, ${1}' % str(number))
    return return_list


def remove_brackets_from_end_of_string(string):
    """
    removes {,},[,] from string
    """
    if string[0] == "[" or string[0] == "(":
        string = string[1:]
    if string[-1] == "]" or string[-1] == ")":
        string = string[:-1]
    return string


def check_if_number_of_optional_args_is_divisible(is_multiple_of, optional_args):
    """
    checks if number of *optional_args is egual to is_equal or is multiple of is_multiple_of
    """
    if len(optional_args) % is_multiple_of:
        raise BaseException("Optional parameters mismatch. Should be multiple of {} but {} given."
                            .format(is_multiple_of, len(optional_args)))


def check_bts_id_type(bts_id):
    """
    Functions checks the type of bts_id and converts it to string in case it is int.
    :param bts_id:
    :return: bts_id:
    """
    if isinstance(bts_id, int):
        bts_id = str(bts_id)
    return bts_id


def warn(message):
    """
    Function prints message into logger
    :param message: message to be printed
    """

    python_logger.log(logging.WARNING, message)


def save_disconnect_logs(target_file_name):
    """Function copies disconnect logs to a given directory"""
    execution_dir = abspath(dirname(sys.argv[0]))
    target_dir = abspath(dirname(target_file_name))
    for listed_file in listdir(execution_dir):
        if 'disconnect' in listed_file and listed_file.endswith('ims2'):
            try:
                copy(join(execution_dir, listed_file), join(target_dir, listed_file))
            except Exception as e:
                warn('Unable to copy file: {}\n{}'.format(listed_file, str(e)))
